package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** A setting's value recorded from a date: it is in force from then until the key's next from-date. */
@Embeddable
public class DatedSetting {

    @Column(name = "setting_key", nullable = false)
    private String key;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    /** The value as text; null for none. */
    @Column(name = "setting_value")
    private String value;

    protected DatedSetting() {
    }

    public DatedSetting(String key, LocalDate fromDate, String value) {
        this.key = key;
        this.fromDate = fromDate;
        this.value = value;
    }

    public String getKey() {
        return key;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public String getValue() {
        return value;
    }
}
-- Dated settings: a setting that carries a figure (the floor, the late percent, the terms, each
-- grade's terms, the clerk limit and the cap) holds a value per from-date. The value in force on a
-- date is the one with the latest from-date on or before it; before every from-date it is the
-- sheet's own column (its starting value). A sheet holds at most one value per key and from-date.
-- A null value means none (no limit, no cap, or the sheet's terms for a grade).
CREATE TABLE sheet_setting (
    sheet_id      VARCHAR(64) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(32) NOT NULL,
    from_date     DATE        NOT NULL,
    setting_value VARCHAR(32)
);
CREATE UNIQUE INDEX sheet_setting_key_from ON sheet_setting (sheet_id, setting_key, from_date);
-- An OPEN claim may be deferred to a date after the sheet's today: until the sheet's today reaches
-- it, the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
-- statement. Null when never deferred; the date is kept once reached.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
-- The sheet's cap: a person's due-total is at most it, the excess shown apart. Null means no cap.
ALTER TABLE sheet ADD COLUMN cap DECIMAL(14, 2);
